let DICT = State.lang==='ar' ? I18N_AR : I18N_EN;
function t(k){return DICT[k]||I18N_EN[k]||k;}
function applyTranslations(){document.documentElement.lang=State.lang; document.documentElement.dir=State.lang==='ar'?'rtl':'ltr'; $$('.[data-i18n]').forEach(n=>{const k=n.dataset.i18n; if(DICT[k]) n.textContent=DICT[k];}); const b=el('langToggleLabel'); if(b)b.textContent=State.lang==='ar'?'EN':'ع';}
function setLang(l){State.lang=l==='ar'?'ar':'en';localStorage.setItem('rewords_lang',State.lang);DICT=State.lang==='ar'?I18N_AR:I18N_EN;applyTranslations();renderPage(State.currentPage);}
function setTheme(v){State.theme=v==='light'?'light':'dark';localStorage.setItem('rewords_theme',State.theme);document.documentElement.dataset.theme=State.theme;const b=el('themeToggle');if(b)b.textContent=State.theme==='dark'?'🌙':'☀️';}
function toast(title,msg,type='info'){const w=el('toastWrap');if(!w)return;const d=document.createElement('div');d.className='toast '+type;d.innerHTML=`<span class="toast-ico">${type==='success'?'✅':type==='error'?'❌':type==='warning'?'⚠️':'ℹ️'}</span><div class="toast-body"><div class="toast-title">${esc(title)}</div><div class="toast-msg">${esc(msg)}</div></div>`;w.appendChild(d);setTimeout(()=>d.remove(),4500);}
function openModal(id){const n=el(id);if(n)n.classList.add('open');}
function closeModal(id){const n=el(id);if(n)n.classList.remove('open');}
let confirmResolve=null;
function askConfirm(title,body,ok='Confirm'){return new Promise(resolve=>{confirmResolve=resolve; el('confirmDialogTitle').textContent=title;el('confirmDialogBody').textContent=body;el('confirmDialogOk').textContent=ok;openModal('confirmDialog');});}
function loading(btn,on){if(!btn)return;btn.disabled=on;btn.dataset.originalText??=btn.textContent;if(on)btn.textContent='Please wait…';else btn.textContent=btn.dataset.originalText;}
async function getCol(name, limit=200){const snap=await db.collection(name).limit(limit).get();return snap.docs.map(d=>({id:d.id,...d.data()}));}
async function safeGet(path){try{const s=await path.get();return s.exists?{id:s.id,...s.data()}:null;}catch(e){console.error(e);return null;}}
function handleErr(e,fallback='Operation failed'){console.error(e);toast('Error',e?.message||fallback,'error');}
function isActive(x){return x.active!==false && x.status!=='disabled';}
function randSafe(n){return Math.floor(Math.random()*n);}

async function loadSettings(){
  const d=await safeGet(db.collection('settings').doc('global'));
  State.settings={...DEFAULT_SETTINGS,...(d||{}),ads:{...DEFAULT_SETTINGS.ads,...(d?.ads||{}),placements:{...DEFAULT_SETTINGS.ads.placements,...(d?.ads?.placements||{})}}};
}
async function loadCatalog(){
  const names=['offers','games','surveys','rewards','providers','faqs','events','promos','posts'];
  const out=await Promise.all(names.map(n=>getCol(n,300).catch(()=>[])));
  [State.offers,State.games,State.surveys,State.rewards,State.providers,State.faqs,State.events,State.promos,State.posts]=out;
  State.offers=State.offers.filter(isActive);State.games=State.games.filter(isActive);State.surveys=State.surveys.filter(isActive);State.rewards=State.rewards.filter(isActive);
}
async function loadUserData(){
  if(!State.user){State.profile=null;State.notifications=[];State.ledger=[];return;}
  State.profile=(await safeGet(db.collection('users').doc(State.user.uid)))||{uid:State.user.uid,email:State.user.email,username:State.user.email?.split('@')[0]||'User',balance:0,status:'active'};
  const u=State.user.uid;
  const [n,l,tickets,refs1,refs2]=await Promise.all([
    db.collection('notifications').where('uid','==',u).limit(200).get().then(s=>s.docs.map(d=>({id:d.id,...d.data()}))).catch(()=>[]),
    db.collection('ledger').where('uid','==',u).limit(500).get().then(s=>s.docs.map(d=>({id:d.id,...d.data()}))).catch(()=>[]),
    db.collection('tickets').where('uid','==',u).limit(100).get().then(s=>s.docs.map(d=>({id:d.id,...d.data()}))).catch(()=>[]),
    db.collection('referrals').where('referredId','==',u).limit(100).get().then(s=>s.docs.map(d=>({id:d.id,...d.data()}))).catch(()=>[]),
    db.collection('referrals').where('referrerId','==',u).limit(100).get().then(s=>s.docs.map(d=>({id:d.id,...d.data()}))).catch(()=>[])
  ]);
  State.notifications=n.sort((a,b)=>(b.ts||0)-(a.ts||0));
  State.ledger=l.sort((a,b)=>(b.ts||0)-(a.ts||0));
  State.tickets=tickets.sort((a,b)=>(b.ts||0)-(a.ts||0));
  const seen=new Set(); State.referrals=[...refs1,...refs2].filter(r=>!seen.has(r.id)&&seen.add(r.id));
}
async function loadPublicStats(){}

function showMaintenance(){const o=el('maintenanceOverlay');if(o)o.classList.add('open');}
function hideMaintenance(){const o=el('maintenanceOverlay');if(o)o.classList.remove('open');}
async function checkMaintenance(){if(State.settings.maintenance && !State.user){showMaintenance();return true;}hideMaintenance();return false;}

function updateBalanceUI(){const b=Number(State.profile?.balance||0);['navBalanceText','homeBalance','wtAvailable','pfBalance','wdAvailable','topupCoinBalance'].forEach(id=>{const n=el(id);if(n)n.textContent=fmt(b);});if(el('navBalance'))el('navBalance').style.display=State.user?'flex':'none';}
function updateAuthUI(){const login=el('loginBtn');if(login)login.innerHTML=State.user?`<span>${esc(State.profile?.username||'Account')}</span>`:'<span data-i18n="auth.login">Login</span>';if(el('logoutBtnMobile'))el('logoutBtnMobile').style.display=State.user?'block':'none';}

function navigate(page){
  if(!PAGES.includes(page))page='home';
  if(AUTH_REQUIRED.has(page)&&!State.user){openModal('authModal');return;}
  if(State.settings.maintenance&&!State.user){showMaintenance();return;}
  State.currentPage=page;PAGES.forEach(p=>{const s=el('page-'+p);if(s)s.classList.toggle('active',p===page);});$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));el('drawer')?.classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});renderPage(page);
}

function emptyState(msg='No data yet.'){return `<div class="empty-state"><div class="es-ico">🗂️</div><div class="es-title">${esc(msg)}</div></div>`;}
function offerCard(o){return `<div class="card offer-card reveal in"><div class="offer-top"><div class="offer-logo">${o.icon||'🎯'}</div><div><div class="offer-name">${esc(o.title||'Offer')}</div><div class="text-xs text-muted">${esc(o.provider||'Provider')}</div></div></div><div class="text-sm text-muted">${esc(o.description||'Complete the offer at the partner site.')}</div><div class="offer-reward">🪙 +${fmt(o.payout||0)}</div><button class="btn btn-accent btn-sm btn-block" data-action="openOffer" data-id="${o.id}">View offer</button></div>`;}
function gameCard(g){const ms=Array.isArray(g.milestones)?g.milestones:[];return `<div class="card game-card reveal in"><div class="game-cover">${g.icon||'🎮'}</div><div class="game-body"><div class="game-title">${esc(g.title||'Game')}</div><div class="text-xs text-muted">${esc(g.platform||'All platforms')}</div><div class="milestones">${ms.slice(0,3).map(m=>`<div class="milestone"><span>${m.icon||'🎯'}</span><div>${esc(m.label||'Milestone')}</div><b>+${fmt(m.reward||0)}</b></div>`).join('')}</div><a class="btn btn-accent btn-sm btn-block mt-2" href="${esc(g.link||'#')}" target="_blank" rel="noopener">Play / Open</a></div></div>`;}
function surveyCard(s){return `<div class="card survey-card reveal in"><div class="survey-ico">${s.icon||'📋'}</div><div class="survey-title">${esc(s.title||'Survey')}</div><div class="text-sm text-muted">${esc(s.description||'Share your opinion.')}</div><div class="survey-meta"><span>${s.minutes||'5'} min</span><b>+${fmt(s.payout||0)}</b></div><button class="btn btn-accent btn-sm btn-block" data-action="openSurvey" data-id="${s.id}">Start survey</button></div>`;}
function rewardCard(r){const disabled=Number(r.stock??1)<=0;return `<div class="card reward-card reveal in"><div class="reward-visual">${r.icon||'🎁'}</div><div class="reward-name">${esc(r.title||'Reward')}</div><div class="text-xs text-muted">${esc(r.category||'Reward')}</div><div class="reward-cost">🪙 ${fmt(r.price??r.cost??0)}</div><div class="text-xs text-muted">Stock: ${r.stock==null?'∞':fmt(r.stock)}</div><button class="btn btn-accent btn-sm btn-block mt-2" data-action="redeemReward" data-id="${r.id}" ${disabled?'disabled':''}>Redeem</button></div>`;}
function providerTabHtml(){return State.providers.filter(isActive).map(p=>`<button class="filter-chip" data-provider="${esc(p.id||p.name)}">${esc(p.name||'Provider')}</button>`).join('');}

function renderHome(){
  const set=(id,v)=>{const n=el(id);if(n)n.textContent=v;};set('heroOffersCount',fmt(State.offers.length));set('heroStatUsers','—');set('heroStatPaid','—');set('heroStatCoins','—');
  set('homeBalance',fmt(State.profile?.balance||0));set('homePending',fmt(State.profile?.pendingBalance||0));set('homeLifetime',fmt(State.profile?.lifetimeEarned||0));set('homeStreak',fmt(State.profile?.streak||0));
  set('tickerTrack',State.settings.announcement||'');set('accountStatusStrip',State.user?`${esc(State.profile?.username||State.user.email||'User')} · ${esc(State.profile?.status||'active')}`:'Please sign in to earn and withdraw.');
  const map={popularRewardsGrid:State.rewards.slice(0,4).map(rewardCard),topOffersGrid:State.offers.slice(0,4).map(offerCard),topGamesGrid:State.games.slice(0,4).map(gameCard),bestSurveysGrid:State.surveys.slice(0,4).map(surveyCard),activeEventsGrid:State.events.filter(e=>e.status==='active'||e.active!==false).slice(0,4).map(e=>`<div class="card"><b>${esc(e.icon||'⚡')} ${esc(e.title||'Event')}</b><div class="text-sm text-muted">${esc(e.subtitle||e.description||'')}</div></div>`),homeFaqList:State.faqs.slice(0,4).map(f=>`<div class="faq-item"><button class="faq-q" data-action="toggleFaq">${esc(f.q||f.question)}<span>＋</span></button><div class="faq-a">${esc(f.a||f.answer)}</div></div>`)};Object.entries(map).forEach(([id,arr])=>{const n=el(id);if(n)n.innerHTML=arr.join('')||emptyState();});
  updateBalanceUI();updateAuthUI();
}
function renderEarn(){renderList('adOpportunitiesList',State.offers.slice(0,6).map(offerCard),'No offers available');renderList('sponsoredTasksList',State.games.slice(0,6).map(gameCard),'No tasks available');renderList('earnOffersGrid',State.offers.map(offerCard),'No offers available');renderAds();}
function renderOffers(){filterGrid('offersGrid',State.offers,el('offersSearch')?.value.toLowerCase()||'',o=>offerCard(o));}
function renderGames(){filterGrid('gamesGrid',State.games,el('gamesSearch')?.value.toLowerCase()||'',gameCard);}
function renderSurveys(){renderList('surveysGrid',State.surveys.map(surveyCard),'No surveys available');}
function renderRewards(){renderList('rewardsGrid',State.rewards.map(rewardCard),'No rewards available');}
function filterGrid(id,data,q,builder){const n=el(id);if(!n)return;const arr=data.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q));n.innerHTML=arr.map(builder).join('')||emptyState();}
function renderList(id,arr,empty){const n=el(id);if(n)n.innerHTML=arr.join('')||emptyState(empty);}
function renderAds(){
  const cfg=State.settings.ads||DEFAULT_SETTINGS.ads;const p=cfg.placements||{};
  const map={'ad-home-banner':p.banner&&cfg.adsterra?.enabled,'ad-watch-native':p.native&&cfg.adsterra?.enabled,'ad-watch-native-watch':p.native&&cfg.adsterra?.enabled,'ad-games-native':p.native&&cfg.adsterra?.enabled,'ad-smartlink':p.smartlink&&cfg.adsterra?.enabled,'monetag-direct-link':p.monetagDirect&&cfg.monetag?.enabled};
  Object.entries(map).forEach(([id,on])=>{const n=el(id);if(n)n.style.display=on?'block':'none';});
  const direct=el('monetag-direct-link');if(direct)direct.href='https://omg10.com/4/11605558';
}
