function renderTopup(){const games=State.rewards.filter(r=>(r.type||'').toLowerCase()==='topup'||String(r.category||'').toLowerCase()==='game top-up');renderList('topupGameList',games.map(g=>`<button class="reward-item ${State.selectedTopupGame?.id===g.id?'selected':''}" data-action="selectTopupGame" data-id="${g.id}" data-game="${esc(g.title)}">${g.icon||'🎮'} ${esc(g.title)}</button>`),'No top-up games configured');if(!State.selectedTopupGame&&games[0])State.selectedTopupGame=games[0];const pg=el('topupPackageGrid');if(pg){const src=(State.selectedTopupGame?.packages?.length?State.selectedTopupGame.packages:[{label:'100 Units',cost:4500},{label:'310 Units',cost:12000},{label:'520 Units',cost:18000}]);if(!State.selectedTopupPackage)State.selectedTopupPackage=src[0];pg.innerHTML=src.map(x=>`<button class="package ${State.selectedTopupPackage?.label===x.label?'selected':''}" data-action="selectPackage" data-cost="${Number(x.cost||0)}" data-label="${esc(x.label||'Package')}"><div class="pkg-name">${esc(x.label||'Package')}</div><div class="pkg-cost">${fmt(x.cost||0)}</div></button>`).join('');}setText('topupCoinBalance',State.profile?.balance||0);setText('topupSumGame',State.selectedTopupGame?.title||'—');setText('topupSumPackage',State.selectedTopupPackage?.label||'—');setText('topupSumCost',fmt(State.selectedTopupPackage?.cost||0));setText('topupSumPlayer',el('topupPlayerId')?.value||'—');setText('topupSumRegion',el('topupRegion')?.value||'—');}
