function renderTransactions(){const type=State.txType||'all';const arr=(State.ledger||[]).filter(x=>type==='all'||x.type===type);renderList('transactionsList',arr.map(l=>`<div class="tx-row"><div><b>${esc(l.description||l.type||'Transaction')}</b><div class="text-xs text-muted">${new Date(l.ts||Date.now()).toLocaleString()}</div></div><strong class="${Number(l.coins)>=0?'text-success':'text-danger'}">${Number(l.coins)>=0?'+':''}${fmt(l.coins)}</strong></div>`),'No transactions');}
