function renderSupport(){setText('supOpen',State.tickets.filter(t=>['open','pending'].includes(t.status)).length);setText('supSolved',State.tickets.filter(t=>t.status==='resolved').length);renderList('myTicketsList',State.tickets.map(t=>`<div class="ticket-row"><b>${esc(t.subject||'Ticket')}</b><span>${esc(t.status||'open')}</span></div>`),'No tickets');renderList('kbGrid',State.faqs.map(f=>`<div class="card"><b>${esc(f.q||f.question)}</b><p>${esc(f.a||f.answer)}</p></div>`),'No help articles');}
