function renderPage(p){const R={home:renderHome,earn:renderEarn,offers:renderOffers,games:renderGames,surveys:renderSurveys,watch:renderWatch,daily:renderDaily,tasks:renderTasks,challenges:renderChallenges,checkin:renderCheckin,streaks:renderStreaks,referral:renderReferral,leaderboard:renderLeaderboard,rewards:renderRewards,topup:renderTopup,withdraw:renderWithdraw,transactions:renderTransactions,notifications:renderNotifications,support:renderSupport,profile:renderProfile,security:renderSecurity,faq:renderFaq,terms:renderTerms,privacy:renderPrivacy,antifraud:renderAntifraud,wallet:renderWallet,promo:renderPromo,events:renderEvents,blog:renderBlog,article:()=>renderBlog(),history:renderHistory,offlinerewards:renderOffline,more:renderMore};try{R[p]?.();applyTranslations();}catch(e){handleErr(e,'Page rendering failed');}}

function setText(id,v){const n=el(id);if(n)n.textContent=v??'';}
function setHtml(id,v){const n=el(id);if(n)n.innerHTML=v??'';}
function setValue(id,v){const n=el(id);if(n)n.value=v??'';}
function setStateText(id,onText,offText){setText(id,onText||offText);}
function setStateButton(id,done,doneText,readyText){const b=el(id);if(!b)return;b.textContent=done?doneText:readyText;b.disabled=!!done;}

async function loadLeaderboard(){try{const s=await db.collection('users').orderBy('lifetimeEarned','desc').limit(20).get();State.leaderboard=s.docs.map(d=>({id:d.id,...d.data()}));}catch(e){State.leaderboard=[];}}
async function refreshAll(){try{await loadSettings();await loadCatalog();if(State.user)await loadUserData();await loadLeaderboard();await checkMaintenance();renderPage(State.currentPage);updateAuthUI();updateBalanceUI();}catch(e){handleErr(e,'Failed to load site data');}}

/* ---- Authentication ---- */
async function login(e){e.preventDefault();if(State.authBusy)return;State.authBusy=true;const b=el('loginBtnSubmit');loading(b,true);try{const email=el('loginEmail').value.trim();const pw=el('loginPassword').value;if(!email||!pw)throw new Error('Email and password are required.');await auth.signInWithEmailAndPassword(email,pw);closeModal('authModal');toast('Welcome','You are signed in.','success');}catch(err){handleErr(err,'Login failed');}finally{loading(b,false);State.authBusy=false;}}
async function signup(e){e.preventDefault();if(State.authBusy)return;State.authBusy=true;const b=el('signupBtnSubmit');loading(b,true);try{if(State.settings.allowSignups===false)throw new Error('New signups are currently disabled.');const username=el('signupUsername').value.trim();const email=el('signupEmail').value.trim();const pw=el('signupPassword').value;if(username.length<3)throw new Error('Username must be at least 3 characters.');if(pw.length<8)throw new Error('Password must be at least 8 characters.');const referralCode=el('signupReferral')?.value.trim().toUpperCase()||'';const cred=await auth.createUserWithEmailAndPassword(email,pw);await db.collection('users').doc(cred.user.uid).set({uid:cred.user.uid,email,username,balance:0,pendingBalance:0,lockedBalance:0,lifetimeEarned:0,lifetimeSpent:0,totalWithdrawn:0,offersCompleted:0,referralCode:username.replace(/[^a-z0-9]/gi,'').slice(0,8).toUpperCase()+'-'+cred.user.uid.slice(0,4).toUpperCase(),referredBy:referralCode||null,status:'active',xp:0,createdAt:ts(),ts:now(),lastSeenAt:ts()});await cred.user.sendEmailVerification();toast('Account created','Verification email sent.','success');closeModal('authModal');openModal('verifyModal');}catch(err){handleErr(err,'Signup failed');}finally{loading(b,false);State.authBusy=false;}}
async function resetPassword(e){e.preventDefault();try{const email=el('forgotEmail').value.trim();if(!email)throw new Error('Enter your email.');await auth.sendPasswordResetEmail(email);toast('Email sent','Password reset instructions were sent.','success');}catch(err){handleErr(err,'Could not send reset email');}}
async function googleLogin(){try{const p=new firebase.auth.GoogleAuthProvider();await auth.signInWithPopup(p);closeModal('authModal');}catch(e){handleErr(e,'Google sign-in failed');}}

/* ---- Truthful earning / atomic user actions ---- */
async function claimDaily(){if(!State.user)return openModal('authModal');const b=el('dailyClaimBtn');loading(b,true);try{const ref=db.collection('daily_claims').doc(State.user.uid+'_'+todayKey());const rewardRef=db.collection('ledger').doc(uid());await db.runTransaction(async tx=>{const [u,c]=await Promise.all([tx.get(db.collection('users').doc(State.user.uid)),tx.get(ref)]);if(c.exists)throw new Error('Already claimed today.');const p=u.data()||{};let streak=Number(p.streak||0);if(p.lastClaimDate!==yesterdayKey()&&p.lastClaimDate!==todayKey())streak=0;streak+=1;const day=((streak-1)%7)+1;const reward=DAILY_PLAN[day-1]*(streak>=7?2:streak>=4?1.5:1);tx.set(ref,{uid:State.user.uid,date:todayKey(),reward,status:'completed',createdAt:ts()});tx.update(u.ref,{balance:(Number(p.balance||0)+reward),lifetimeEarned:inc(reward),streak,bestStreak:Math.max(Number(p.bestStreak||0),streak),lastClaimDate:todayKey(),lastDailyClaimId:ref.id,xp:inc(5)});tx.set(rewardRef,{uid:State.user.uid,type:'daily',coins:reward,description:'Daily reward · day '+day,status:'completed',reference:ref.id,ts:now(),createdAt:ts()});});await loadUserData();renderPage(State.currentPage);showRewardPopup('Daily reward','+'+fmt(State.profile?.lastClaimDate===todayKey()?State.profile?.dailyReward||0:0));toast('Reward claimed','Your daily reward was credited.','success');}catch(e){handleErr(e,'Daily claim failed');}finally{loading(b,false);}}
function deterministicDailyReward(type){return type==='wheel'?150:(FIXED_DAILY_GAMES[type]||100);}
async function claimDailyGame(type){if(!State.user)return openModal('authModal');const field={wheel:'wheelSpunDate',scratch:'scratchDate',mystery:'mysteryDate',treasure:'treasureDate'}[type];const col=type+'_claims';const key=State.user.uid+'_'+todayKey();const reward=deterministicDailyReward(type);try{const claim=db.collection(col).doc(key),userRef=db.collection('users').doc(State.user.uid),ledger=db.collection('ledger').doc(uid());await db.runTransaction(async tx=>{const c=await tx.get(claim);if(c.exists)throw new Error('Already claimed today.');const u=await tx.get(userRef);const p=u.data()||{};tx.set(claim,{uid:State.user.uid,date:todayKey(),reward,status:'completed',createdAt:ts()});tx.update(userRef,{balance:Number(p.balance||0)+reward,lifetimeEarned:inc(reward),[field]:todayKey(),lastDailyGameClaimId:claim.id,lastDailyGameType:type});tx.set(ledger,{uid:State.user.uid,type:'daily',coins:reward,description:type+' daily bonus',status:'completed',reference:claim.id,ts:now(),createdAt:ts()});});await loadUserData();renderDaily();showRewardPopup(type,'+'+fmt(reward));}catch(e){handleErr(e,'Daily bonus failed');}}
async function spinWheel(){const w=el('spinWheel');try{await claimDailyGame('wheel');}catch(e){}}
async function scratchCard(){await claimDailyGame('scratch');}
async function openMystery(){await claimDailyGame('mystery');}
async function openTreasure(){await claimDailyGame('treasure');}

async function redeemReward(id){if(!State.user)return openModal('authModal');const r=State.rewards.find(x=>x.id===id);if(!r)return;const price=Number(r.price??r.cost??0);if(price<=0)return toast('Unavailable','Reward price is not configured.','warning');try{const orderRef=db.collection('orders').doc('reward_'+uid());const claimRef=db.collection('reward_claims').doc(State.user.uid+'_'+id+'_'+Date.now());const userRef=db.collection('users').doc(State.user.uid),rewardRef=db.collection('rewards').doc(id);await db.runTransaction(async tx=>{const [u,rd]=await Promise.all([tx.get(userRef),tx.get(rewardRef)]);const p=u.data()||{};const rr=rd.data()||{};const stock=rr.stock==null?Infinity:Number(rr.stock);if(stock<=0)throw new Error('Out of stock.');if(Number(p.balance||0)<price)throw new Error('Insufficient coins.');if(rr.stock!=null)tx.update(rewardRef,{stock:stock-1});tx.update(userRef,{balance:Number(p.balance||0)-price,lifetimeSpent:inc(price),lastOrderId:orderRef.id});tx.set(orderRef,{uid:State.user.uid,type:'reward',rewardId:id,item:rr.title||r.title,cost:price,status:'pending',reference:orderRef.id,createdAt:ts(),ts:now()});tx.set(claimRef,{uid:State.user.uid,rewardId:id,orderId:orderRef.id,price,createdAt:ts()});});await loadUserData();renderRewards();toast('Order created','Your reward order is pending admin fulfillment.','success');}catch(e){handleErr(e,'Reward redemption failed');}}
async function openOfferModal(id){const o=State.offers.find(x=>x.id===id);if(!o)return;openModal('offerModal');setText('offerModalTitle',o.title||'Offer');setHtml('offerModalBody',`<p>${esc(o.description||'')}</p><p class="text-muted">Reward: +${fmt(o.payout||0)} coins after provider verification.</p><a class="btn btn-accent" href="${esc(o.link||'#')}" target="_blank" rel="noopener" data-action="recordOfferClick" data-id="${o.id}">Open offer</a>`);}
async function recordOfferClick(id){try{await db.collection('offer_clicks').add({uid:State.user.uid,offerId:id,createdAt:ts(),ts:now(),status:'clicked'});toast('Offer opened','Coins are credited only after provider verification.','info');}catch(e){}closeModal('offerModal');}
async function openSurveyModal(id){const s=State.surveys.find(x=>x.id===id);if(!s)return;openModal('surveyModal');setText('surveyModalTitle',s.title||'Survey');setHtml('surveyModalBody',`<p>${esc(s.description||'')}</p><p class="text-muted">Reward: +${fmt(s.payout||0)} coins after provider verification.</p><a class="btn btn-accent" href="${esc(s.link||'#')}" target="_blank" rel="noopener" data-action="recordSurveyClick" data-id="${s.id}">Open survey</a>`);}
async function recordSurveyClick(id){try{await db.collection('survey_clicks').add({uid:State.user.uid,surveyId:id,createdAt:ts(),ts:now(),status:'clicked'});toast('Survey opened','Coins are credited only after provider verification.','info');}catch(e){}closeModal('surveyModal');}
async function watchAd(){if(!State.user)return openModal('authModal');const cap=Number(State.settings.adDailyCap||15),used=State.profile?.adsDate===todayKey()?Number(State.profile.adsWatchedToday||0):0;if(used>=cap)return toast('Limit reached','Daily ad limit reached.','warning');renderWatch();const links=[];if(State.settings.ads?.monetag?.enabled&&State.settings.ads?.placements?.monetagDirect)links.push('https://omg10.com/4/11605558');if(State.settings.ads?.adsterra?.enabled&&State.settings.ads?.placements?.smartlink)links.push('https://www.effectivecpmnetwork.com/z4tps2vcr?key=4f9ed7a11b0bab57c48fbe6c874b5a18');if(!links.length)return toast('Ads unavailable','No ad placement is enabled.','warning');await db.collection('ad_view_requests').add({uid:State.user.uid,date:todayKey(),provider:'redirect',placement:'rewarded',status:'pending',createdAt:ts(),ts:now()});window.open(links[0],'_blank','noopener');toast('Ad opened','Reward is pending provider verification; this button cannot self-credit coins.','info');}
async function promoApply(code){if(!State.user)return openModal('authModal');code=(code||el('promoInput')?.value||'').trim().toUpperCase();if(!code)return toast('Promo','Enter a promo code.','warning');try{const promoSnap=await db.collection('promos').where('code','==',code).limit(1).get();if(promoSnap.empty)throw new Error('Invalid promo code.');const promo={id:promoSnap.docs[0].id,...promoSnap.docs[0].data()};const claim=db.collection('promo_claims').doc(State.user.uid+'_'+code),userRef=db.collection('users').doc(State.user.uid),ledger=db.collection('ledger').doc(uid());await db.runTransaction(async tx=>{const [c,u]=await Promise.all([tx.get(claim),tx.get(userRef)]);if(c.exists)throw new Error('This code was already used.');if(promo.active===false)throw new Error('Promo is inactive.');const reward=Number(promo.reward||0);const p=u.data()||{};tx.set(claim,{uid:State.user.uid,code,promoId:promo.id,reward,createdAt:ts()});tx.update(userRef,{balance:Number(p.balance||0)+reward,lifetimeEarned:inc(reward),lastPromoClaimId:claim.id});tx.set(ledger,{uid:State.user.uid,type:'promo',coins:reward,description:'Promo code: '+code,status:'completed',reference:claim.id,ts:now(),createdAt:ts()});});await loadUserData();renderPromo();toast('Promo applied','+'+fmt(promo.reward||0)+' coins.','success');}catch(e){handleErr(e,'Promo failed');}}
async function submitWithdrawal(){if(!State.user)return openModal('authModal');const amount=Number(el('wdAmount')?.value||0),details={paypalEmail:el('wdPaypalEmail')?.value?.trim()||''};const min=Number(State.settings.minWithdraw||10000);if(amount<min) return toast('Withdrawal','Minimum is '+fmt(min)+' coins.','warning');if(amount>Number(State.profile?.balance||0))return toast('Withdrawal','Insufficient balance.','warning');try{const userRef=db.collection('users').doc(State.user.uid),lock=db.collection('withdrawal_locks').doc(State.user.uid),wd=db.collection('withdrawals').doc(uid()),ledger=db.collection('ledger').doc(uid());await db.runTransaction(async tx=>{const [u,l]=await Promise.all([tx.get(userRef),tx.get(lock)]);if(l.exists)throw new Error('You already have a pending withdrawal.');const p=u.data()||{};if(Number(p.balance||0)<amount)throw new Error('Insufficient balance.');const fee=Math.round(amount*Number(State.settings.withdrawalFeePct||0)/100);tx.set(lock,{uid:State.user.uid,withdrawalId:wd.id,amount,createdAt:ts()});tx.update(userRef,{balance:Number(p.balance||0)-amount,pendingWithdrawal:amount,lockedBalance:inc(amount),lastWithdrawalId:wd.id});tx.set(wd,{uid:State.user.uid,amount,fee,receive:amount-fee,method:State.selectedWdMethod,details,status:'pending',createdAt:ts(),ts:now()});tx.set(ledger,{uid:State.user.uid,type:'withdrawal',coins:-amount,description:'Withdrawal request',status:'pending',reference:wd.id,ts:now(),createdAt:ts()});});await loadUserData();renderWithdraw();renderWallet();toast('Withdrawal submitted','Your withdrawal is pending review.','success');}catch(e){handleErr(e,'Withdrawal failed');}}
async function submitTopup(){if(!State.user)return openModal('authModal');const game=State.selectedTopupGame,pack=State.selectedTopupPackage;if(!game||!pack)return toast('Top up','Select game and package first.','warning');const cost=Number(pack.cost||0);try{const uref=db.collection('users').doc(State.user.uid),order=db.collection('orders').doc('topup_'+uid());await db.runTransaction(async tx=>{const u=await tx.get(uref),p=u.data()||{};if(Number(p.balance||0)<cost)throw new Error('Insufficient coins.');tx.update(uref,{balance:Number(p.balance||0)-cost,lifetimeSpent:inc(cost),lastOrderId:order.id});tx.set(order,{uid:State.user.uid,type:'topup',game:game.title,gameId:game.id,package:pack.label,cost,playerId:el('topupPlayerId')?.value?.trim()||'',region:el('topupRegion')?.value||'',serverId:el('topupServerId')?.value?.trim()||'',status:'pending',createdAt:ts(),ts:now()});});await loadUserData();renderTopup();toast('Top-up created','Your top-up order is pending fulfillment.','success');}catch(e){handleErr(e,'Top-up failed');}}
async function applyReferral(){if(!State.user)return openModal('authModal');const code=el('refCodeInput')?.value.trim().toUpperCase();if(!code)return toast('Referral','Enter a code.','warning');try{const current=State.profile?.referredBy;if(current)throw new Error('A referrer is already assigned.');const q=await db.collection('users').where('referralCode','==',code).limit(1).get();if(q.empty)throw new Error('Invalid referral code.');const ref=q.docs[0];if(ref.id===State.user.uid)throw new Error('You cannot use your own referral code.');await db.collection('referrals').doc(State.user.uid).set({referredId:State.user.uid,referrerId:ref.id,code,createdAt:ts(),status:'pending'});await db.collection('users').doc(State.user.uid).update({referredBy:ref.id});await loadUserData();renderReferral();toast('Referral applied','Referral has been attached to your account.','success');}catch(e){handleErr(e,'Referral failed');}}
async function createTicket(){if(!State.user)return openModal('authModal');const subject=prompt('Subject');if(!subject)return;const body=prompt('Describe the issue');if(!body)return;try{await db.collection('tickets').add({uid:State.user.uid,subject,body,status:'open',priority:'normal',createdAt:ts(),ts:now()});await loadUserData();renderSupport();toast('Ticket sent','Support ticket created.','success');}catch(e){handleErr(e,'Could not create ticket');}}
async function saveProfile(){if(!State.user)return;const username=el('editUsername')?.value.trim();const country=el('editCountry')?.value.trim();if(username&&username.length<3)return toast('Profile','Username is too short.','warning');try{await db.collection('users').doc(State.user.uid).update({username,country,lastSeenAt:ts()});await loadUserData();closeModal('profileEditModal');renderProfile();toast('Profile','Profile updated.','success');}catch(e){handleErr(e,'Could not save profile');}}
async function deleteAccount(){if(!State.user)return;const ok=await askConfirm('Delete account','This will permanently disable your account and revoke sign-in.','Delete');if(!ok)return;try{await db.collection('users').doc(State.user.uid).update({status:'deleted',deletedAt:ts()});await auth.currentUser.delete();toast('Account deleted','Your account was deleted.','success');}catch(e){handleErr(e,'Account deletion failed');}}
async function logout(){await auth.signOut().catch(()=>{});navigate('home');}
async function openArticle(id){const p=State.posts.find(x=>x.id===id);if(!p)return;navigate('article');setHtml('articleBody',`<article class="card"><h1>${esc(p.title)}</h1><p>${esc(p.content||'')}</p></article>`);}
function showRewardPopup(title,msg){setText('rewardPopupAmount',title);setText('rewardPopupMsg',msg||'');openModal('rewardPopup');}

function bindEvents(){
  document.addEventListener('click',async e=>{
    const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();navigate(nav.dataset.nav);return;}
    const act=e.target.closest('[data-action]');if(act){e.preventDefault();const a=act.dataset.action,id=act.dataset.id;try{
      if(a==='openAuth')openModal('authModal'); else if(a==='logout')logout(); else if(a==='openOffer')openOfferModal(id); else if(a==='recordOfferClick')recordOfferClick(id); else if(a==='openSurvey')openSurveyModal(id); else if(a==='recordSurveyClick')recordSurveyClick(id); else if(a==='redeemReward')redeemReward(id); else if(a==='watchAd')watchAd(); else if(a==='applyPromo')promoApply(act.dataset.code); else if(a==='markNotif'){await db.collection('notifications').doc(id).update({read:true});await loadUserData();renderNotifications();} else if(a==='selectTopupGame'){State.selectedTopupGame=State.rewards.find(r=>r.id===id)||null;State.selectedTopupPackage=null;renderTopup();} else if(a==='selectPackage'){State.selectedTopupPackage={cost:Number(act.dataset.cost||0),label:act.dataset.label||''};setText('topupSumCost',fmt(State.selectedTopupPackage.cost));setText('topupSumPackage',State.selectedTopupPackage.label);} else if(a==='selectWdMethod'){State.selectedWdMethod=act.dataset.method||'PayPal';$$('#wdMethodList .wd-method').forEach(x=>x.classList.toggle('selected',x===act));updateWdSummary();} else if(a==='toggleFaq')act.closest('.faq-item')?.classList.toggle('open'); else if(a==='openTicket')createTicket(); else if(a==='openArticle')openArticle(id);
    }catch(err){handleErr(err);}};
  });
  $$('[data-toggle-pw]').forEach(b=>b.addEventListener('click',()=>{const i=el(b.dataset.togglePw);if(i)i.type=i.type==='password'?'text':'password';}));
  el('langToggle')?.addEventListener('click',()=>setLang(State.lang==='ar'?'en':'ar'));
  el('notifBtn')?.addEventListener('click',()=>navigate('notifications'));
  el('rewardPopupOk')?.addEventListener('click',()=>closeModal('rewardPopup'));
  el('secPhoneBtn')?.addEventListener('click',()=>toast('Security','Phone verification requires a Firebase phone provider and OTP flow; it is not faked here.','info'));
  $$('#page-withdraw .chip[data-amount]').forEach(b=>b.addEventListener('click',()=>{setValue('wdAmount',b.dataset.amount);updateWdSummary();}));
  ['topupPlayerId','topupRegion'].forEach(id=>el(id)?.addEventListener('input',()=>{setText('topupSumPlayer',el('topupPlayerId')?.value||'—');setText('topupSumRegion',el('topupRegion')?.value||'—');}));
  el('themeToggle')?.addEventListener('click',()=>setTheme(State.theme==='dark'?'light':'dark'));
  el('hamburger')?.addEventListener('click',()=>el('drawer')?.classList.add('open'));
  el('drawerScrim')?.addEventListener('click',()=>el('drawer')?.classList.remove('open'));
  el('toTopBtn')?.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'}));
  el('loginForm')?.addEventListener('submit',login);el('signupForm')?.addEventListener('submit',signup);el('forgotForm')?.addEventListener('submit',resetPassword);
  el('googleLoginBtn')?.addEventListener('click',googleLogin);el('authModalClose')?.addEventListener('click',()=>closeModal('authModal'));el('verifyCloseBtn')?.addEventListener('click',()=>closeModal('verifyModal'));
  el('resendVerifyBtn')?.addEventListener('click',async()=>{try{await auth.currentUser?.sendEmailVerification();toast('Verification','Email resent.','success')}catch(e){handleErr(e)}});el('verifyContinueBtn')?.addEventListener('click',()=>closeModal('verifyModal'));
  el('forgotPwLink')?.addEventListener('click',()=>{el('loginForm')?.classList.add('hidden');el('forgotForm')?.classList.remove('hidden');});el('forgotBackBtn')?.addEventListener('click',()=>{el('forgotForm')?.classList.add('hidden');el('loginForm')?.classList.remove('hidden');});
  el('confirmDialogCancel')?.addEventListener('click',()=>{closeModal('confirmDialog');confirmResolve?.(false);confirmResolve=null;});el('confirmDialogOk')?.addEventListener('click',()=>{closeModal('confirmDialog');confirmResolve?.(true);confirmResolve=null;});
  el('authTabLogin')?.addEventListener('click',()=>{el('authTabLogin').classList.add('active');el('authTabSignup').classList.remove('active');el('loginForm').classList.remove('hidden');el('signupForm').classList.add('hidden');el('forgotForm').classList.add('hidden');});el('authTabSignup')?.addEventListener('click',()=>{el('authTabSignup').classList.add('active');el('authTabLogin').classList.remove('active');el('loginForm').classList.add('hidden');el('signupForm').classList.remove('hidden');el('forgotForm').classList.add('hidden');});
  el('maintenanceRetryBtn')?.addEventListener('click',refreshAll);
  el('dailyClaimBtn')?.addEventListener('click',claimDaily);el('spinWheelBtn')?.addEventListener('click',spinWheel);el('scratchCover')?.addEventListener('click',scratchCard);el('mysteryBox')?.addEventListener('click',openMystery);el('treasureChest')?.addEventListener('click',openTreasure);el('watchAdBtn')?.addEventListener('click',watchAd);el('dailyAdBonusBtn')?.addEventListener('click',watchAd);el('interstitialBtn')?.addEventListener('click',watchAd);el('checkinBtn')?.addEventListener('click',claimDaily);
  el('refCopyBtn')?.addEventListener('click',async()=>{await navigator.clipboard?.writeText(el('refLinkInput')?.value||'');toast('Referral','Link copied.','success')});el('pfRefCopyBtn')?.addEventListener('click',async()=>{await navigator.clipboard?.writeText(State.profile?.referralCode||'');toast('Referral','Code copied.','success')});el('refShareBtn')?.addEventListener('click',async()=>{const u=el('refLinkInput')?.value||location.href;if(navigator.share)await navigator.share({title:'Rewords',url:u});else await navigator.clipboard?.writeText(u);toast('Referral','Share link copied.','success')});el('refApplyBtn')?.addEventListener('click',applyReferral);
  el('topupConfirmBtn')?.addEventListener('click',submitTopup);el('wdConfirmBtn')?.addEventListener('click',submitWithdrawal);el('wdAmount')?.addEventListener('input',updateWdSummary);
  el('markAllReadBtn')?.addEventListener('click',async()=>{if(!State.user)return;const q=await db.collection('notifications').where('uid','==',State.user.uid).get();const batch=db.batch();q.docs.forEach(d=>batch.update(d.ref,{read:true}));await batch.commit();await loadUserData();renderNotifications();});el('clearNotifBtn')?.addEventListener('click',async()=>{if(!State.user)return;const q=await db.collection('notifications').where('uid','==',State.user.uid).get();const batch=db.batch();q.docs.forEach(d=>batch.delete(d.ref));await batch.commit();await loadUserData();renderNotifications();});
  el('chatSend')?.addEventListener('click',()=>{const input=el('chatInput'),body=el('chatBody');const q=input?.value.trim();if(!q||!body)return;body.insertAdjacentHTML('beforeend',`<div class="msg user"><div>${esc(q)}</div></div>`);input.value='';const low=q.toLowerCase();let a='Please open a support ticket for account-specific help.';if(low.includes('withdraw'))a='For withdrawals, choose a method, enter an amount above the minimum, then submit. Each user can have only one pending withdrawal.';else if(low.includes('earn')||low.includes('offer'))a='Complete partner offers and wait for provider verification before coins are credited.';else if(low.includes('promo'))a='Use the Promo Codes page and enter an active code once.';body.insertAdjacentHTML('beforeend',`<div class="msg admin"><div>${esc(a)}</div></div>`);body.scrollTop=body.scrollHeight;});el('editProfileBtn')?.addEventListener('click',()=>{setValue('editUsername',State.profile?.username||'');setValue('editCountry',State.profile?.country||'');openModal('profileEditModal');});el('profileEditClose')?.addEventListener('click',()=>closeModal('profileEditModal'));el('saveProfileBtn')?.addEventListener('click',saveProfile);el('deleteAccountBtn')?.addEventListener('click',deleteAccount);
  el('secVerifyEmailBtn')?.addEventListener('click',async()=>{try{if(auth.currentUser?.emailVerified)return toast('Security','Email is already verified.','info');await auth.currentUser?.sendEmailVerification();toast('Security','Verification email sent.','success')}catch(e){handleErr(e)}});el('secPasswordBtn')?.addEventListener('click',async()=>{const pw=prompt('Enter a new password (8+ characters)');if(!pw||pw.length<8)return;try{await auth.currentUser.updatePassword(pw);toast('Security','Password changed.','success')}catch(e){handleErr(e,'Password change failed')}});el('sec2faBtn')?.addEventListener('click',()=>toast('2FA','True Firebase MFA enrollment needs a configured second factor; no fake 2FA is enabled here.','info'));
  el('promoApplyBtn')?.addEventListener('click',()=>promoApply());
  el('txTypeFilter')?.addEventListener('click',e=>{const b=e.target.closest('[data-type]');if(!b)return;$$('#txTypeFilter [data-type]').forEach(x=>x.classList.toggle('active',x===b));State.txType=b.dataset.type;renderTransactions();});
  el('earnSearch')?.addEventListener('input',()=>filterGrid('earnOffersGrid',State.offers,el('earnSearch').value.toLowerCase(),offerCard));el('offersSearch')?.addEventListener('input',renderOffers);el('gamesSearch')?.addEventListener('input',renderGames);
}

auth.onAuthStateChanged(async user=>{State.user=user;if(user){await loadUserData();if(!user.emailVerified){}}else{State.profile=null;State.notifications=[];State.ledger=[];}updateAuthUI();await refreshAll();if(user&&State.currentPage==='home')renderHome();});

async function boot(){setTheme(State.theme);applyTranslations();bindEvents();await refreshAll();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.navigate=navigate;window.toast=toast;window.closeModal=closeModal;window.openModal=openModal;
